def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    import heapq

    if not jobs:
        return 0
    if k >= len(jobs):
        return sum(pay for _, _, pay in jobs)

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u, v, capacity, cost):
        graph[u].append([v, len(graph[v]), capacity, cost])
        graph[v].append([u, len(graph[u]) - 1, 0, -cost])

    for u in range(n - 1):
        add_edge(u, u + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest-path potentials in the forward DAG.
    potential = [0] * n
    for u in range(n):
        for v, _, capacity, cost in graph[u]:
            if capacity:
                potential[v] = min(potential[v], potential[u] + cost)

    source, sink = 0, n - 1
    flow = 0
    total_cost = 0
    infinity = float("inf")

    while flow < k:
        distance = [infinity] * n
        previous_vertex = [-1] * n
        previous_edge = [-1] * n
        distance[source] = 0
        heap = [(0, source)]

        while heap:
            current_distance, u = heapq.heappop(heap)
            if current_distance != distance[u]:
                continue

            for edge_index, (v, _, capacity, cost) in enumerate(graph[u]):
                if not capacity:
                    continue

                candidate = current_distance + cost + potential[u] - potential[v]
                if candidate < distance[v]:
                    distance[v] = candidate
                    previous_vertex[v] = u
                    previous_edge[v] = edge_index
                    heapq.heappush(heap, (candidate, v))

        if distance[sink] == infinity:
            break

        for v in range(n):
            if distance[v] != infinity:
                potential[v] += distance[v]

        amount = k - flow
        v = sink
        while v != source:
            u = previous_vertex[v]
            edge = graph[u][previous_edge[v]]
            amount = min(amount, edge[2])
            v = u

        v = sink
        while v != source:
            u = previous_vertex[v]
            edge = graph[u][previous_edge[v]]
            edge[2] -= amount
            graph[v][edge[1]][2] += amount
            total_cost += amount * edge[3]
            v = u

        flow += amount

    return -total_cost
